CREATE TYPE "Category" AS ENUM (E'software', E'networks', E'embedded', E'battlebot');

CREATE TYPE "ProjectType" AS ENUM (E'diploma', E'class', E'extra');

CREATE TABLE "_CreatorToProject" (
    "A" integer NOT NULL,
    "B" integer NOT NULL
);

CREATE TABLE "creator" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "createdat" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updatedat" timestamp(3) without time zone NOT NULL,
    "deletedat" timestamp(3) without time zone,
    "name" text NOT NULL,
    "email" text NOT NULL,
    "phone" text,
    "grade" integer NOT NULL,
    "class" text NOT NULL
);

CREATE TABLE "picture" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "createdat" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updatedat" timestamp(3) without time zone NOT NULL,
    "deletedat" timestamp(3) without time zone,
    "url" text NOT NULL,
    "isthumbnail" boolean DEFAULT false NOT NULL,
    "projectid" integer NOT NULL
);

CREATE TABLE "project" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "createdat" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updatedat" timestamp(3) without time zone NOT NULL,
    "deletedat" timestamp(3) without time zone,
    "name" text NOT NULL,
    "description" text,
    "type" "ProjectType" NOT NULL,
    "category" "Category" NOT NULL,
    "mentor" text,
    "videolink" text,
    "hasthumbnail" boolean DEFAULT false NOT NULL,
    "demolink" text,
    "githublink" text
);

CREATE TABLE "vote" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "createdat" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updatedat" timestamp(3) without time zone NOT NULL,
    "deletedat" timestamp(3) without time zone,
    "name" text NOT NULL,
    "email" text NOT NULL,
    "verified" boolean DEFAULT false NOT NULL,
    "networksid" integer NOT NULL,
    "softwareid" integer NOT NULL,
    "embeddedid" integer NOT NULL,
    "battlebotid" integer NOT NULL
);

ALTER TABLE "creator" ADD CONSTRAINT "creator_email_key" UNIQUE ("email");

ALTER TABLE "creator" ADD CONSTRAINT "creator_pkey" PRIMARY KEY ("id");

ALTER TABLE "picture" ADD CONSTRAINT "picture_pkey" PRIMARY KEY ("id");

ALTER TABLE "picture" ADD CONSTRAINT "picture_url_key" UNIQUE ("url");

ALTER TABLE "project" ADD CONSTRAINT "project_pkey" PRIMARY KEY ("id");

ALTER TABLE "vote" ADD CONSTRAINT "vote_email_key" UNIQUE ("email");

ALTER TABLE "vote" ADD CONSTRAINT "vote_name_key" UNIQUE ("name");

ALTER TABLE "vote" ADD CONSTRAINT "vote_pkey" PRIMARY KEY ("id");

CREATE INDEX "_CreatorToProject_B_index" ON "_CreatorToProject" ("B");

CREATE INDEX "creator_class_idx" ON "creator" ("class");

CREATE INDEX "creator_grade_idx" ON "creator" ("grade");

CREATE INDEX "picture_projectid_idx" ON "picture" ("projectid");

CREATE INDEX "project_category_idx" ON "project" ("category");

CREATE INDEX "project_type_idx" ON "project" ("type");

CREATE INDEX "vote_battlebotid_idx" ON "vote" ("battlebotid");

CREATE INDEX "vote_embeddedid_idx" ON "vote" ("embeddedid");

CREATE INDEX "vote_networksid_idx" ON "vote" ("networksid");

CREATE INDEX "vote_softwareid_idx" ON "vote" ("softwareid");

CREATE UNIQUE INDEX "_CreatorToProject_AB_unique" ON "_CreatorToProject" ("A", "B");

ALTER TABLE "_CreatorToProject" ADD CONSTRAINT "_CreatorToProject_A_fkey" FOREIGN KEY ("A") REFERENCES "creator" ("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "_CreatorToProject" ADD CONSTRAINT "_CreatorToProject_B_fkey" FOREIGN KEY ("B") REFERENCES "project" ("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "picture" ADD CONSTRAINT "picture_projectid_fkey" FOREIGN KEY ("projectid") REFERENCES "project" ("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "vote" ADD CONSTRAINT "vote_battlebotid_fkey" FOREIGN KEY ("battlebotid") REFERENCES "project" ("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "vote" ADD CONSTRAINT "vote_embeddedid_fkey" FOREIGN KEY ("embeddedid") REFERENCES "project" ("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "vote" ADD CONSTRAINT "vote_networksid_fkey" FOREIGN KEY ("networksid") REFERENCES "project" ("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "vote" ADD CONSTRAINT "vote_softwareid_fkey" FOREIGN KEY ("softwareid") REFERENCES "project" ("id") ON DELETE CASCADE ON UPDATE CASCADE;
